import json

with open('table.json') as f:
    table = json.load(f)

with open('start.txt') as f:
    start = f.read().strip()

symbols = sorted(set(''.join(table.keys()) + ''.join(table.values())))

# Check if changing the left symbol gives a consistent permutation of outputs
# For fixed a1, a2: table[a1,b,c] -> table[a2,b,c] should be a fixed permutation
a1, a2 = 'A', 'B'
v1_to_v2 = {}
consistent = True
for b in symbols:
    for c in symbols:
        v1 = table[a1+b+c]
        v2 = table[a2+b+c]
        if v1 in v1_to_v2:
            if v1_to_v2[v1] != v2:
                consistent = False
        else:
            v1_to_v2[v1] = v2

print(f"Consistent for left A->B: {consistent}")
print(f"Mapping: {v1_to_v2}")

# Check for all pairs of left symbols
all_consistent = True
for a1 in symbols:
    for a2 in symbols:
        mapping = {}
        ok = True
        for b in symbols:
            for c in symbols:
                v1 = table[a1+b+c]
                v2 = table[a2+b+c]
                if v1 in mapping:
                    if mapping[v1] != v2:
                        ok = False
                        break
                else:
                    mapping[v1] = v2
            if not ok:
                break
        if not ok:
            all_consistent = False
            print(f"Inconsistent for left {a1}->{a2}")
            break
    if not all_consistent:
        break

print(f"All left pairs consistent: {all_consistent}")

# Same check for right symbol
all_consistent_right = True
for c1 in symbols:
    for c2 in symbols:
        mapping = {}
        ok = True
        for a in symbols:
            for b in symbols:
                v1 = table[a+b+c1]
                v2 = table[a+b+c2]
                if v1 in mapping:
                    if mapping[v1] != v2:
                        ok = False
                        break
                else:
                    mapping[v1] = v2
            if not ok:
                break
        if not ok:
            all_consistent_right = False
            break
    if not all_consistent_right:
        break

print(f"All right pairs consistent: {all_consistent_right}")

# Same for middle
all_consistent_mid = True
for b1 in symbols:
    for b2 in symbols:
        mapping = {}
        ok = True
        for a in symbols:
            for c in symbols:
                v1 = table[a+b1+c]
                v2 = table[a+b2+c]
                if v1 in mapping:
                    if mapping[v1] != v2:
                        ok = False
                        break
                else:
                    mapping[v1] = v2
            if not ok:
                break
        if not ok:
            all_consistent_mid = False
            break
    if not all_consistent_mid:
        break

print(f"All middle pairs consistent: {all_consistent_mid}")
